this.validateSwift = function (view) {
	regexString = /^(?![\s])[a-zA-Z0-9.,()\/='+:?!\"%&*<>;{@#_ \r\n\s-]*$/;
	regex = new RegExp(regexString);
	if (view.getData() != "") {
		if (!regex.test(view.getData())){
			 view.setValid(false,"Only Allowed characters is: Alphanumeric and . , – ( ) / = ‘ + : ? ! ” % & * < > ; { @ # _ CrLf Space");
		}
		else{
			view.setValid(true);
		}
	}
}

