}

this.prepareAdvice = function () {
	// Initialize with default values
	const stepName = this.context.options.step.get("value");
	const requestType = this.context.options.requestType.get("value");
	const productCode = this.context.options.productCode.get("value");
	const isChecker = this.context.options.isChecker.get("value");
	const stage = this.context.options.stage.get("value");

	// Set default visibility to NONE
	this.context.options.adviceVis.set("value", "NONE");

	// Exit early if no product code or is special case
	if (!productCode || isChecker || ["ICAP", "IDC Payment"].includes(requestType)) {
		return;
	}

	// Determine event code based on conditions
	let event = "";
	if (stepName === "liq") {
		event = "LIQD";
	} else if (requestType === "IDC Amendment") {
		event = "AMND";
	} else if (stage) {
		event = stage.toLowerCase() === "initial" ? "BOOK" : "INIT";
	}
	// Clear any existing advice message
	this.context.options.adviceMsg.set("value", "");

	// Execute advice code with concatenated value
	const concated = event + "-" + productCode;
	this.ui.get("GetAdviceCode").execute(concated);
};


