const isInitial = this.context.binding.get("value").get("IDCRequestStage").toLowerCase() == "initial" || false;
const isChecker = this.context.options.isChecker?.get("value") || false;
const isUpdateReq = this.context.binding.get("value").get("IDCRequestNature").get("id") == 2;

// ProductCode visibility rules
console.log("isChecker:", isChecker, "isInitial:", isInitial, "isUpdateReq:", isUpdateReq);

if (!isChecker) {
    // Not checker: Enable if initial OR (final AND not update request)
    const shouldEnable = isInitial || (!isInitial && !isUpdateReq);
    this.ui.get("ProductCode").setEnabled(shouldEnable);
    console.log("ProductCode enabled:", shouldEnable);
} else {
    // Checker: Always disabled
    this.ui.get("ProductCode").setEnabled(false);
}
	

// if (this.context.binding.get("value").get("IDCRequestNature").get("id") == 2) {
// 	this.ui.get("ProductCode").setEnabled(false);
// }

if (this.context.options.isChecker.get("value") == false && this.context.binding.get("value").get("IDCRequestType").get("englishdescription") == "Advance Payment") {
	this.context.options.billVis.set("value", "EDITABLE");
} else {
	this.context.options.billVis.set("value", "DEFAULT");
}

this.isReqAmend = this.context.binding.get("value").get("IDCRequestType").get("englishdescription").toLowerCase().includes("amend") || false;

// Set operation type field editability based on request type.
const editableRequestTypes = ["IDC Acknowledgement", "IDC Execution", "IDC Completion", "IDC Amendment"];

const currentRequestType = this.context.binding.get("value").get("IDCRequestType").get("englishdescription");
const isEditableRequestType = editableRequestTypes.includes(currentRequestType);
this.ui.get("operationType").setEnabled(isEditableRequestType && !isChecker);

