//-------------------------Multitenor-----------------------------------
this.setPaymentTermsVis = function (me, isChange) {
	var isMaker = !this.context.options.isChecker.get("value");
	if (!isChange) {
		var isFinalAmend = this.context.binding.get("value").get("IDCRequestState").toLowerCase() == "final" && this.isReqAmend;
		me.setEnabled(isMaker && !isFinalAmend);
	}

	// control vis related to payment terms
	const transitDays = this.getViewByPath("/DC_Templete1/6/TransitDays");
	const tenorDays = this.getViewByPath("/DC_Templete1/6/TenorDays");
	const maturityDate = this.getViewByPath("/DC_Templete1/6/MaturityDate");
