// on load of view and change of action
this.checkRecallStatus = function () {
	var requestNum = this.context.binding.get("value").get("instanceID") || "";
	if (!requestNum) return;
	this.ui.get("checkRecallStatus").execute(requestNum);
};

// on result of ajax call Check Recall Status
this.getRecallResults = function (isExist) {
	if (isExist) {
		this.ui.get("recallMsg").setData("Request is Recalled");
		this.actionsController("recall", "");
	} else {
		this.actionsController("step", "");
	}
};

// called from getRecallResults and also on change of approvals.
this.actionsController = function (actionType, makerAction) {
	var requestType = this.requestType;
	var requestNature = this.requestNature;
	console.log("requestType: ", requestType);
	var updateList = ["IDC Withdrawal", "IDC Reversal", "IDC Customs Release"]; // static for now but can be replaced with ids
	if (updateList.indexOf(requestType) > -1) return;

	var taskId = this.context.bpm.system.taskId;
	var requestNum = this.context.binding.get("value").get("instanceID") || "";
	var lastAction = "";
	if (actionType != "recall") {
		lastAction = makerAction || this.lastAction || this.context.options.makerAction?.get("value");
		actionType = actionType || "step";
		// get approvals - get the checkboxes
		var cadBox = this.ui.get("/DC_Templete1/approvals1/obainCADApprovalCheckBox");
		var complianceBox = this.ui.get("/DC_Templete1/approvals1/Check_box3");
		var treasuryBox = this.ui.get("/DC_Templete1/approvals1/Check_box2");
		if (cadBox && complianceBox && treasuryBox) {
			// get the values of the checkboxes
			var isChecker = !cadBox.isEnabled() && !complianceBox.isEnabled() && !treasuryBox.isEnabled();
			var cadApproval = cadBox.isChecked() && !isChecker;
			var complianceApproval = complianceBox.isChecked() && complianceBox.isEnabled();
			var treasuryApproval = treasuryBox.isChecked() && treasuryBox.isEnabled();
			//			console.log("isCHecker: ", isChecker, "cadApproval: ", cadApproval);
			if (cadApproval || complianceApproval || treasuryApproval) {
				actionType = "approve";
			}
		}
	}

	// execute the ajax service
	var callInput = taskId + "&" + actionType + "&" + lastAction + "&" + requestNature + "&" + requestNum + "&" + requestType;
	console.log("Actions Controller Input: ", callInput);
	this.ui.get("getActionsCall").execute(callInput);
};

