// Helper function to get the date part only without time
function getDateOnly(date) {
	const d = new Date(date);
	return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

// Helper function to format the date to "yyyy-MM-dd"
function formatDate(date) {
	if (!date) return;
	const year = date.getFullYear();
	const month = String(date.getMonth() + 1).padStart(2, "0"); // Months are 0-indexed
	const day = String(date.getDate()).padStart(2, "0");
	return `${year}-${month}-${day}`;
}
// reusable function to prevent negative value on input (only works on input not on change)
this.preventNegativeInput = function (me) {
	// Add an event listener to the input field of the Integer control
	me.context.element.addEventListener("input", function (event) {
		// Get the current value of the input
		var currentValue = event.target.value;

		// If the value starts with a '-' prevent it
		if (currentValue.startsWith("-")) {
			event.target.value = currentValue.replace("-", "");
		}
	});
};

// calulate amount payable by NBE and outstanding amount
this.calcAmtPayNBE = function () {
	const requestType = this.context.options.requestType.get("value");
	const contractStage = this.contractStage || "";
	// Check if calculation is needed
	const requiresCalculation = ["Advance Payment", "ICAP", "IDC Acknowledgement", "IDC Execution", "IDC Completion"].includes(requestType) || (requestType == "IDC Amendment" && contractStage.toLowerCase() == "initial");

	if (requiresCalculation) {
		const documentAmount = this.context.binding.get("value").get("documentAmount") || 0;
		const discountAmount = this.context.binding.get("value").get("discountAmt") || 0;
		const amountAdvanced = this.context.binding.get("value").get("amountAdvanced") || 0;
		const amountPaidByOtherBanks = this.context.binding.get("value").get("amtPaidbyOtherBanks") || 0;

		// Calculate payable amount
		var payable = documentAmount - discountAmount - amountAdvanced - amountPaidByOtherBanks;
		this.context.binding.get("value").set("amtPayableByNBE", payable.toFixed(2));
		//		this.context.binding.get("value").set("outstandingAmount", payable.toFixed(2));
		this.ui.get("OutstandingAmount").setData(payable.toFixed(2));

		// Validate result
		if (payable < 0) {
			this.ui.get("AmountPayablebyNBE").setValid(false, "Amount must be greater than 0");
			return;
		}

		// Special validation for ICAP
		if (requestType === "ICAP" && payable > 0) {
			this.ui.get("AmountPayablebyNBE").setValid(false, "Warning: Amount is greater than 0 for ICAP request");
			return;
		}

		this.ui.get("AmountPayablebyNBE").setValid(true);
	}
};

this.calculateAmountPayableByNBE = function () {
	const requestType = this.context.options.requestType.get("value");
	const contractStage = this.contractStage || "";
	// Check if calculation is needed
	const requiresCalculation = ["Advance Payment", "ICAP", "IDC Acknowledgement", "IDC Execution", "IDC Completion"].includes(requestType) || (requestType === "IDC Amendment" && contractStage.toLowerCase() == "initial");

	if (requiresCalculation) {
		const documentAmount = this.context.binding.get("value").get("documentAmount") || 0;
		const discountAmount = this.context.binding.get("value").get("discountAmt") || 0;
		const amountAdvanced = this.context.binding.get("value").get("amountAdvanced") || 0;
		const amountPaidByOtherBanks = this.context.binding.get("value").get("amtPaidbyOtherBanks") || 0;

		// Calculate payable amount
		const payable = documentAmount - discountAmount - amountAdvanced - amountPaidByOtherBanks;
		this.context.binding.get("value").set("amtPayableByNBE", payable.toFixed(2));
		this.context.binding.get("value").set("outstandingAmount", payable.toFixed(2));

		// Validate result
		if (payable < 0) {
			this.ui.get("AmountPayablebyNBE").setValid(false, "Amount must be greater than 0");
			return;
		}

		// Special validation for ICAP
		if (requestType === "ICAP" && payable > 0) {
			this.ui.get("AmountPayablebyNBE").setValid(false, "Warning: Amount is greater than 0 for ICAP request");
			return;
		}

		this.ui.get("AmountPayablebyNBE").setValid(true);
	}
};

