	var payable = this.context.binding.get("value").get("amtPayableByNBE");
	var sum = this.context.binding.get("value").get("amtSight") + this.context.binding.get("value").get("amtDeferredNoAvalized") + this.context.binding.get("value").get("amtDeferredAvalized");
	if (sum != payable) {
		avalizationFlag = false;
		this.ui.get("AmountSight").setValid(false, "please ensure that the follwing fields is equal to Amount Payable by NBE:Amount Sight,Amount Deferred - No Avalization,Amount Deferred - Avalization");
		this.ui.get("AmountDeferredNoAvalization").setValid(false, "please ensure that the follwing fields is equal to Amount Payable by NBE:Amount Sight,Amount Deferred - No Avalization,Amount Deferred - Avalization");
		this.ui.get("AmountDeferredAvalization").setValid(false, "please ensure that the follwing fields is equal to Amount Payable by NBE:Amount Sight,Amount Deferred - No Avalization,Amount Deferred - Avalization");
	} else {
