};

this.checkPartiAlavalization = function () {
	var noAvalization = this.ui.get("AmountDeferredNoAvalization").getData();
	var avalization = this.ui.get("AmountDeferredAvalization").getData();
	if (avalization > 0 && noAvalization > 0) {
		this.ui.get("AmountDeferredNoAvalization").setValid(false, "partial avalization not allowed");
		this.ui.get("AmountDeferredAvalization").setValid(false, "partial avalization not allowed");
