this.setDefaultAmnt = function () {
	var index = chargesIndex;
	if (!!this.context.options.dAmount.get("value")) {
		var amount = this.context.options.dAmount.get("value").toFixed(2);
		this.context.binding.get("value").get(index).set("defaultAmount", amount);
		this.context.binding.get("value").get(index).set("chargeAmount", amount);
	} else {
		this.context.binding.get("value").get(index).set("defaultAmount", 0);
		this.context.binding.get("value").get(index).set("chargeAmount", 0);
	}
};

this.calcChangeAmnt = function (value) {
	var index = value.ui.getIndex();
	if (this.context.options.hubStep.get("value") == "LIQD") {
		event = "LIQD";
		requestAmnt = this.context.options.idcContract.get("value").get("liquidationSummary").get("liquidationAmt");
	} else if (this.context.options.hubStep.get("value") == "HUB" && this.context.options.requestType.get("value") == "IDC Amendment") {
		event = "AMND";
		requestAmnt = this.context.options.amtPayableByNBE.get("value");
	} else {
		event = this.context.options.stage.get("value");
		requestAmnt = this.context.options.amtPayableByNBE.get("value");
	}
	//	var amtPayableByNBE = this.context.options.amtPayableByNBE.get("value");

	var changePercentage = this.context.binding.get("value").get(index).get("changePercentage");
	var concatedDefault = requestAmnt + "," + changePercentage + "," + this.context.options.appID.get("value");

	this.ui.get("calculateChangeAmount1[" + index + "]").execute(concatedDefault);
	newIndex = index;
};

this.setChargeAmnt = function () {
	var index = newIndex;
	if (!!this.context.options.changeAmount.get("value")) {
		var changeAmount = this.context.options.changeAmount.get("value");

		this.context.binding.get("value").get(index).set("chargeAmount", changeAmount);
	} else {
		this.context.binding.get("value").get(index).set("chargeAmount", 0);
	}
};

this.amountValidation = function (value) {
	var index = value.ui.getIndex();
	if (value.getData() < 0 || value.getData() > 100) {
		value.setData(0);
		value.setValid(false, "Must be >= 0 and < 100");
	} else {
		value.setValid(true);
		this.calcChangeAmnt(value);
	}
};
