this.GetAccounts = function (index, newtxt) {
	// Get PartyTable items
	var tableItems = this.ui.get("PartyTable").getData().items;

	// Update the CIF for the selected party
	tableItems[index].partyCIF = newtxt;

	// Filter partyCIFs for specific party types
	var filteredCIFs = tableItems
		.filter(function (item) {
			return item.partyType && (item.partyType.name === "Accountee" || item.partyType.name === "Drawee" || item.partyType.name === "Case in Need");
		})
		.map(function (item) {
			return item.partyCIF;
		});

	// Join filtered CIFs with hyphen separator
	var CIFS = filteredCIFs.join("-");

	var tabs = this.ui.getAbsoluteName().split("/");

	// remove the last part of the path
	tabs.pop();
	// add 7 as the last part of the path (charges)
	tabs.push("7");
	var Path = tabs.join("/");
	Path += "/getCustomerAccounts";
	var getAccountsService = bpmext.ui.getView(Path);

	// Execute the getCustomerAccounts service with the filtered CIF list
	// var getAccountsService = bpmext.ui.getView("/DC_Templete1/7/getCustomerAccounts");
	if (getAccountsService) {
		getAccountsService.execute(CIFS);
	}
};

