// validate data before retrieve or recall - on click of retrieve and recall button
this.validateRecall = function (caller) {
	var isFound = this.context.options.isRequestFound.get("value");
	if (caller == "Retrieve" || caller == "Recall") {
		// validate req number before retrieve
		var reqNum = this.ui.get("requestNumber");
		reqNum.setValid(true);
		const regex = /^(\d{14}|\d{14}-\d{2})$/;

		if (!reqNum.getData()) {
			reqNum.setValid(false, "Please Enter a Request Number");
			return false;
		}

		if (!regex.test(reqNum.getData().trim())) {
			reqNum.setValid(false, "Please Enter a valid Request Number");
			return false;
		}
	}

	if (caller == "Recall") {
		// validate reason before recall
		var reason = this.ui.get("recallReason");
		reason.setValid(true);
		if(this.context.options.notFoundMsg.get("value") && this.context.options.notFoundMsg.get("value") != ""){
			return false;
		}
		
		if (!reason.getData()) {
			reason.setValid(false, "Please Enter a Recall Reason");
			return false;
		}

		if (!isFound) {
			reason.setValid(false, "Please Enter a Recall Reason");
			return false;
		}
		
		this.ui.get("confirmLayout").setVisible(true);
		return true;
		//${confirmLayout}.setVisible(true)
	}
};

