.tab-name:hover {
	text-decoration: underline;
	color: #d35400;
}

.tab-container {
	display: flex;
	flex-direction: column;
	width: 100%;
}

.tab-header {
	display: flex;
	align-items: center;
	width: 100%;
}

/* Style for the gradient box */
.gradient-box {
	flex: 1;
	padding: 10px 20px;
	background: linear-gradient(45deg, rgba(255, 255, 255, 0.8), rgba(240, 240, 240, 0.8));
	cursor: pointer;
	border-radius: 4px;
	transition: transform 0.2s ease, background-color 0.2s ease;
	display: flex;
	align-items: center;
}

.gradient-box:hover {
	transform: scale(1.05);
	background: linear-gradient(45deg, rgba(255, 255, 255, 1), rgba(240, 240, 240, 1));
}

.tab {
	position: relative;
	width: 100%;
}

.tab::after {
	content: attr(error-count);
	color: red;
	font-size: 10px;
	position: absolute;
	right: 5px;
	top: 5px;
}

/* Add animation for the highlighted field */
.highlighted-field {
	animation-name: highlight;
	animation-duration: 1.5s;
}

@keyframes highlight {
	from {
		background-color: yellow;
	}
	to {
		background-color: initial;
	}
}

.error-list {
	display: none;
	margin-left: 20px;
	padding: 0;
	list-style-type: none;
	transition: max-height 0.2s ease-out;
	overflow: hidden;
}

.error-list.collapsed {
	max-height: 0;
}

.error-list.expanded {
	max-height: 500px; /* Adjust this value as needed */
}

.bullet {
	color: #ff8c00; /* Replaced red with a shade of orange */
	margin-right: 5px; /* Adjust spacing between bullet and link */
}

.message-link {
	cursor: pointer;
	color: #8a1412; /* Replaced red with a shade of orange */
	text-decoration: none;
	padding: 5px; /* Add padding for better hover area */
	transition: color 0.2s ease, background-color 0.2s ease; /* Add transition for smooth animation */
	position: relative;
}

.message-link:hover {
	text-decoration: underline;
	color: #d35400; /* Darker shade of orange on hover */
	/* background-color: rgba(255, 140, 0, 0.1); */
}

_this = this;

var displayText = "Display_Text1";
const generalTab = "GENERAL";
var tabSectionId = "";
var tabSection = "";
const errorSectionId = "ErrorSection_Panel1";
const stopVU = this.context.options.stop.get("value") || false;
const runTime = this.context.options.runTimeValid.get("value") || false;
const initExpanded = this.context.options.initExpanded?.get("value") || true;

_this.startVU = function () {
	tabSection = document.querySelector('[role="tablist"]');
	tabSectionId = _this.getTabSectionId(tabSection);
	const redCircles = document.querySelectorAll(".red-circle");

	var viewErrorList = [];
	viewErrorList = bpmext.ui.getInvalidViews();

	if (viewErrorList.length == 0) {
		this.ui.get(displayText).setText("");
		_this.ui.get(errorSectionId).setVisible(false, true);
		_this.resetRedCircle(redCircles);
		return;
	}

	const errMapList = viewErrorList
		.map((view) => _this.constructErrorMap(view))
		.filter(function (obj) {
			return obj != null;
		});

	var viewMapList = [];
	_this.resetRedCircle(redCircles);
	viewMapList = _this.organizeErrorsByTab(errMapList);
	console.dir(viewMapList);
	// Add counter red circle
	_this.resetRedCircle(redCircles);
	viewMapList.forEach((viewMap) => _this.addRedCircleToTab(viewMap));

	//Add panel with tabs and messages
	_this.ui.get(errorSectionId).setVisible(true, true);
	setTimeout(() => {
		_this.constructValidPanel(viewMapList);
	}, 200);
};

_this.getTabInfoFirst = function (tabSection) {
	const tabElementList = tabSection?.children;
	var tabsInfo = {};
	for (var i = 0; i < tabElementList.length; i++) {
		var tabElement = tabElementList[i];

		var tabInnerText = tabElement.innerText.split("\n")[0].replaceAll(" ", "");
		if (!tabInnerText || tabElement.getAttribute("role") !== "tab") continue;

		tabsInfo[tabInnerText] = {
			tabDomID: tabElement.id,
			tabPathId: i,
		};
	}

	return tabsInfo;
};

_this.resetRedCircle = function (redCircles) {
	// const redCircles = document.querySelectorAll(".red-circle");
	if (!redCircles) return;
	redCircles.forEach((circle) => circle.remove());
};

_this.getTabSectionId = function (tabSection) {
	if (!tabSection) return;
	var currentElement = tabSection;

	while (currentElement && currentElement !== document.body) {
		if (currentElement.classList.contains("Tab_Section")) {
			tabSectionId = currentElement.getAttribute("control-name");
			break;
		}

		currentElement = currentElement.parentElement;
	}

	return tabSectionId;
};

_this.constructValidPanel = function (viewMapList) {
	if (!viewMapList || viewMapList.length == 0) return;
	var tabNameListHTML = ``;

	for (var i = 0; i < viewMapList.length; i++) {
		var tabData = viewMapList[i].tab;
		var messageList = viewMapList[i].messages;

		if (!tabData) continue;

		var tabDomId = tabData.domId;
		var tabName = tabData.name || generalTab;
		var errorListId = `error-list-${tabDomId}`;
		var tabIndex = tabData.pathId;
		var errorListHTML = _this.generateErrorListHTML(messageList, tabName, tabIndex);

		tabNameListHTML += _this.generateTabItemHTML(tabName, tabDomId, errorListId, tabIndex, errorListHTML);
	}

	tabNameListHTML = `<ul class="tab-list">${tabNameListHTML}</ul>`;
	_this.ui.get(displayText).setText(tabNameListHTML);
};

_this.activateTab = function (tabDomId, tabName, tabIndex) {
	if (!tabName || !tabIndex) return;

	if (tabName !== generalTab) {
		page.ui.get(tabSectionId).setCurrentPane(tabIndex);
		if (tabDomId) {
			var tabElement = document.getElementById(tabDomId);
			_this.highLighElement(tabElement);
		}
	}
};

_this.activateField = function (tabName, panelString, tabIndex, fieldPathId) {
	const panelList = panelString.split("@@").filter((e) => e !== "");

	if (tabIndex && tabSectionId && tabName !== generalTab) {
		page.ui.get(tabSectionId).setCurrentPane(tabIndex);
	}
	if (panelList && panelList.length > 0) {
		for (let i = 0; i < panelList.length; i++) {
			page.ui.get(panelList[i]).expand();
		}
	}
	if (!fieldPathId) return;

	setTimeout(() => {
		_this.focusOnElement(fieldPathId);
	}, 300);
};

_this.focusOnElement = function (fieldPathId) {
	var fieldElement = page.ui.get(fieldPathId).context.element;
	_this.highLighElement(fieldElement);

	page.ui.get(fieldPathId).focus();
};

_this.highLighElement = function (fieldElement) {
	if (!fieldElement) return;

	fieldElement.classList.add("highlighted-field");
	setTimeout(function () {
		fieldElement.classList.remove("highlighted-field");
	}, 1500);
};

_this.addRedCircleToTab = function (viewMap) {
	if (!viewMap.tab.domId) return;

	const messagesCount = viewMap.messages.length;
	const tabDomId = viewMap.tab.domId;
	const tabElement = document.getElementById(tabDomId);
	if (!tabElement) return;

	// Combine DOM reads
	const existingCircle = tabElement.querySelector(".red-circle");
	const newCircleContent = `<div class="red-circle">${messagesCount}</div>`;

	// Combine DOM writes
	if (!existingCircle) {
		tabElement.insertAdjacentHTML("beforeend", newCircleContent);
	} else {
		existingCircle.innerText = messagesCount;
	}
};

_this.constructErrorMap = function (fieldElement) {
	if (!fieldElement || !fieldElement.context.element || !fieldElement._bpmextViewNode) return null;

	var fieldDomId = fieldElement.context.element.id;
	var fieldParents = _this.getFieldParents(fieldDomId);
      // var isField = Object.keys(fieldElement._bpmextViewNode._data.context.subview).length === 0;
      var isField = true;
	if (isField) {
		errorMap = {
			field: {
				message: fieldElement._bpmextVE?.errors?.[0]?.message || "",
				domId: fieldDomId,
				pathId: fieldElement.context.element.getAttribute("control-name"),
				viewId: fieldElement.context.element.getAttribute("data-viewid"),
				label: fieldElement.getLabel(),
			},

			panels: fieldParents.cPanelList /*[list of "SPARKCPanel"]*/,

			view: fieldParents.viewObj,
		};
		return errorMap;
	}
};

_this.getFieldParents = function (elementId) {
	var fieldParents = {
		viewObj: {
			name: "",
			domId: "",
			pathId: "",
		},
		cPanelList: [],
	};
	const cPanelClass = "Collapsible_Panel";
	const tabClass = "tab-pane";

	var currentElement = document.getElementById(elementId);

	while (currentElement && currentElement !== document.body) {
		if (currentElement.classList.contains(tabClass)) {
			fieldParents.viewObj.name = currentElement.getAttribute("aria-label");
			fieldParents.viewObj.domId = currentElement.id;
			fieldParents.viewObj.pathId = currentElement.getAttribute("control-name");
		} else if (currentElement.classList.contains(cPanelClass)) {
			fieldParents.cPanelList.unshift(currentElement.getAttribute("control-name"));
		}

		currentElement = currentElement.parentNode;
	}
	console.dir(fieldParents);
	return fieldParents;
};

_this.organizeErrorsByTab = function (errorList) {
	const viewMap = new Map();
	let tabsInfo = {};

	if (tabSection) {
		tabsInfo = _this.getTabInfoFirst(tabSection);
	}

	errorList.forEach((error) => {
		if (error) {
			const viewName = error.view.name;
			const sanitizedViewName = viewName?.replaceAll(" ", "");

			if (!viewMap.has(viewName)) {
				viewMap.set(viewName, {
					view: {
						name: viewName,
						domId: error.view.domId,
						pathId: error.view.pathId,
					},
					messages: [],
					tab: {
						name: viewName,
						domId: tabsInfo[sanitizedViewName]?.tabDomID,
						pathId: tabsInfo[sanitizedViewName]?.tabPathId,
					},
				});
			}
			// Add the error message to the corresponding tab entry
			const viewEntry = viewMap.get(viewName);
			viewEntry.messages.push({
				message: error.field.message,
				field: {
					domId: error.field.domId,
					pathId: error.field.pathId,
					viewId: error.field.viewId,
					label: error.field.label,
					panels: [...error.panels],
				},
			});
		}
	});
	// Convert the map values to an array of tab objects
	return [...viewMap.values()];
};

_this.generateTabItemHTML = function (tabName, tabDomId, errorListId, tabIndex, errorListHTML) {
	const initialButtonText = initExpanded ? "Hide" : "Show";
	const initialDisplayStyle = initExpanded ? "block" : "none";
	return `<li class="tab-item">
            <div class="tab-container">
                <div class="tab-header">
                    <div class="gradient-box">
                        <a href="#${tabDomId}" class="tab-name"
                            onclick="_this.toggleErrorList('${errorListId}'); event.preventDefault(); event.stopPropagation();">${tabName}</a>
                    </div>
                </div>
                <ul id="${errorListId}" class="error-list" style="display: ${initialDisplayStyle};">${errorListHTML}</ul>
            </div>
        </li>`;
};

_this.generateErrorListHTML = function (listOfErrors, tabName, tabIndex) {
	return listOfErrors
		.map(function (error) {
			const fieldDomId = error.field.domId;
			const fieldPathId = error.field.pathId;
			const label = error.field.label;
			const targetMessage = `<b>${label}</b> : ${error.message}`;
			const panelString = error.field.panels.join("@@");

			return `<li><span class="bullet">&#8226;</span> <a href="#${fieldDomId}" class="message-link" message-id="${fieldDomId}" onclick="_this.activateField('${tabName}','${panelString}','${tabIndex}','${fieldPathId}');">${targetMessage}</a></li>`;
		})
		.join("");
};

_this.toggleErrorList = function (errorListId) {
	const errorList = document.getElementById(errorListId);
	if (errorList) {
		const isCollapsed = errorList.style.display === "none" || !errorList.style.display;
		errorList.style.display = isCollapsed ? "block" : "none";
		//   if (button) {
		//       button.textContent = isCollapsed ? "Hide" : "Show";
		//   }
	}
};
